CREATE TABLE IF NOT EXISTS `catalog_generation` (`generation_id` TEXT NOT NULL, `provider` TEXT NOT NULL, `format` TEXT NOT NULL, `content_uri` TEXT NOT NULL, `display_name` TEXT NOT NULL, `source_uri` TEXT, `source_version` TEXT, `source_date_epoch_seconds` INTEGER, `source_date_nano` INTEGER, `observed_at_epoch_seconds` INTEGER NOT NULL, `observed_at_nano` INTEGER NOT NULL, `content_sha256` TEXT NOT NULL, `observed_bytes` INTEGER NOT NULL, `language_scope` TEXT NOT NULL, `payload_schema_version` INTEGER NOT NULL, `parser_version` TEXT NOT NULL, `notice_payload` TEXT, `oracle_count` INTEGER NOT NULL, `face_count` INTEGER NOT NULL, `printing_count` INTEGER NOT NULL, `status` TEXT NOT NULL, `activated_at_epoch_seconds` INTEGER, `activated_at_nano` INTEGER, `input_kind` TEXT NOT NULL DEFAULT 'USER_CONTENT_URI', `artifact_job_id` TEXT, `source_payload` TEXT, PRIMARY KEY(`generation_id`));
CREATE INDEX IF NOT EXISTS `index_catalog_generation_status` ON `catalog_generation` (`status`);
CREATE INDEX IF NOT EXISTS `index_catalog_generation_provider_status` ON `catalog_generation` (`provider`, `status`);
CREATE TABLE IF NOT EXISTS `catalog_active` (`dataset_key` TEXT NOT NULL, `generation_id` TEXT NOT NULL, PRIMARY KEY(`dataset_key`), FOREIGN KEY(`generation_id`) REFERENCES `catalog_generation`(`generation_id`) ON UPDATE NO ACTION ON DELETE NO ACTION );
CREATE INDEX IF NOT EXISTS `index_catalog_active_generation_id` ON `catalog_active` (`generation_id`);
CREATE TABLE IF NOT EXISTS `oracle_card` (`generation_id` TEXT NOT NULL, `provider` TEXT NOT NULL, `oracle_id` TEXT NOT NULL, `language` TEXT NOT NULL, `name` TEXT NOT NULL, `original_text` TEXT, `normalized_name` TEXT NOT NULL, `normalized_search_text` TEXT NOT NULL, `canonical_digest` TEXT NOT NULL, `record_payload` TEXT NOT NULL, PRIMARY KEY(`generation_id`, `provider`, `oracle_id`, `language`), FOREIGN KEY(`generation_id`) REFERENCES `catalog_generation`(`generation_id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_oracle_card_lookup_order` ON `oracle_card` (`generation_id`, `language`, `normalized_name`, `provider`, `oracle_id`);
CREATE TABLE IF NOT EXISTS `card_face` (`generation_id` TEXT NOT NULL, `provider` TEXT NOT NULL, `oracle_id` TEXT NOT NULL, `language` TEXT NOT NULL, `face_index` INTEGER NOT NULL, `provider_face_id` TEXT, `name` TEXT NOT NULL, `face_payload` TEXT NOT NULL, PRIMARY KEY(`generation_id`, `provider`, `oracle_id`, `language`, `face_index`), FOREIGN KEY(`generation_id`, `provider`, `oracle_id`, `language`) REFERENCES `oracle_card`(`generation_id`, `provider`, `oracle_id`, `language`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `printing` (`generation_id` TEXT NOT NULL, `provider` TEXT NOT NULL, `printing_id` TEXT NOT NULL, `oracle_provider` TEXT, `oracle_id` TEXT, `oracle_language` TEXT, `set_code` TEXT NOT NULL, `set_name` TEXT, `collector_number` TEXT NOT NULL, `language` TEXT NOT NULL, `rarity` TEXT, `finishes` TEXT, `image_uri` TEXT, `metadata_payload` TEXT NOT NULL, PRIMARY KEY(`generation_id`, `provider`, `printing_id`), FOREIGN KEY(`generation_id`) REFERENCES `catalog_generation`(`generation_id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`generation_id`, `oracle_provider`, `oracle_id`, `oracle_language`) REFERENCES `oracle_card`(`generation_id`, `provider`, `oracle_id`, `language`) ON UPDATE NO ACTION ON DELETE NO ACTION );
CREATE INDEX IF NOT EXISTS `index_printing_oracle` ON `printing` (`generation_id`, `oracle_provider`, `oracle_id`, `oracle_language`);
CREATE INDEX IF NOT EXISTS `index_printing_set_number` ON `printing` (`generation_id`, `set_code`, `collector_number`, `language`);
CREATE TABLE IF NOT EXISTS `printing_oracle_membership` (`generation_id` TEXT NOT NULL, `printing_provider` TEXT NOT NULL, `printing_id` TEXT NOT NULL, `source_slot` INTEGER NOT NULL, `source_kind` TEXT NOT NULL, `oracle_provider` TEXT NOT NULL, `oracle_id` TEXT NOT NULL, `oracle_language` TEXT NOT NULL, PRIMARY KEY(`generation_id`, `printing_provider`, `printing_id`, `source_slot`), FOREIGN KEY(`generation_id`, `printing_provider`, `printing_id`) REFERENCES `printing`(`generation_id`, `provider`, `printing_id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`generation_id`, `oracle_provider`, `oracle_id`, `oracle_language`) REFERENCES `oracle_card`(`generation_id`, `provider`, `oracle_id`, `language`) ON UPDATE NO ACTION ON DELETE NO ACTION );
CREATE INDEX IF NOT EXISTS `index_printing_oracle_membership_lookup` ON `printing_oracle_membership` (`generation_id`, `oracle_provider`, `oracle_id`, `oracle_language`, `printing_provider`, `printing_id`);
CREATE TABLE IF NOT EXISTS `printing_face_asset` (`generation_id` TEXT NOT NULL, `provider` TEXT NOT NULL, `printing_id` TEXT NOT NULL, `face_index` INTEGER NOT NULL, `provider_face_id` TEXT, `language` TEXT NOT NULL, `printed_name` TEXT, `asset_payload` TEXT NOT NULL, PRIMARY KEY(`generation_id`, `provider`, `printing_id`, `face_index`), FOREIGN KEY(`generation_id`, `provider`, `printing_id`) REFERENCES `printing`(`generation_id`, `provider`, `printing_id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE VIRTUAL TABLE IF NOT EXISTS `catalog_name_fts` USING FTS5(`name`, `text`, `generation_id` UNINDEXED, `provider` UNINDEXED, `oracle_id` UNINDEXED, `language` UNINDEXED, tokenize=`unicode61 remove_diacritics 2`);
CREATE TABLE IF NOT EXISTS `rules_corpus` (`generation_id` TEXT NOT NULL, `provider` TEXT NOT NULL, `language` TEXT NOT NULL, `status` TEXT NOT NULL, `content_uri` TEXT NOT NULL, `display_name` TEXT NOT NULL, `source_payload` TEXT NOT NULL, `provenance_payload` TEXT NOT NULL, `upstream_version` TEXT, `effective_at_epoch_seconds` INTEGER, `effective_at_nano` INTEGER, `source_date_epoch_seconds` INTEGER, `source_date_nano` INTEGER, `source_uri` TEXT, `observed_at_epoch_seconds` INTEGER NOT NULL, `observed_at_nano` INTEGER NOT NULL, `content_sha256` TEXT NOT NULL, `observed_bytes` INTEGER NOT NULL, `entry_count` INTEGER NOT NULL, `reference_count` INTEGER NOT NULL, `payload_schema_version` INTEGER NOT NULL, `activated_at_epoch_seconds` INTEGER, `activated_at_nano` INTEGER, `input_kind` TEXT NOT NULL DEFAULT 'USER_CONTENT_URI', `artifact_job_id` TEXT, PRIMARY KEY(`generation_id`));
CREATE INDEX IF NOT EXISTS `index_rules_corpus_provider_status` ON `rules_corpus` (`provider`, `status`);
CREATE TABLE IF NOT EXISTS `rules_active` (`singleton_id` INTEGER NOT NULL, `generation_id` TEXT NOT NULL, PRIMARY KEY(`singleton_id`), FOREIGN KEY(`generation_id`) REFERENCES `rules_corpus`(`generation_id`) ON UPDATE NO ACTION ON DELETE NO ACTION );
CREATE INDEX IF NOT EXISTS `index_rules_active_generation_id` ON `rules_active` (`generation_id`);
CREATE TABLE IF NOT EXISTS `rule_entry` (`corpus_id` TEXT NOT NULL, `provider` TEXT NOT NULL, `local_id` TEXT NOT NULL, `kind` TEXT NOT NULL, `number` TEXT, `title` TEXT, `text` TEXT NOT NULL, `ordinal` INTEGER NOT NULL, `entry_payload` TEXT NOT NULL, PRIMARY KEY(`corpus_id`, `provider`, `local_id`), FOREIGN KEY(`corpus_id`) REFERENCES `rules_corpus`(`generation_id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE UNIQUE INDEX IF NOT EXISTS `index_rule_entry_corpus_ordinal` ON `rule_entry` (`corpus_id`, `ordinal`);
CREATE TABLE IF NOT EXISTS `rule_reference` (`corpus_id` TEXT NOT NULL, `from_provider` TEXT NOT NULL, `from_local_id` TEXT NOT NULL, `ref_ordinal` INTEGER NOT NULL, `raw_target` TEXT NOT NULL, `resolved_provider` TEXT, `resolved_local_id` TEXT, `evidence_payload` TEXT NOT NULL, PRIMARY KEY(`corpus_id`, `from_provider`, `from_local_id`, `ref_ordinal`), FOREIGN KEY(`corpus_id`, `from_provider`, `from_local_id`) REFERENCES `rule_entry`(`corpus_id`, `provider`, `local_id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `rules_import_attempt` (`attempt_id` TEXT NOT NULL, `generation_id` TEXT, `source_payload` TEXT NOT NULL, `attempt_payload` TEXT NOT NULL, `phase` TEXT NOT NULL, `started_at_epoch_seconds` INTEGER NOT NULL, `started_at_nano` INTEGER NOT NULL, `finished_at_epoch_seconds` INTEGER, `finished_at_nano` INTEGER, `failure_payload` TEXT, `payload_schema_version` INTEGER NOT NULL, PRIMARY KEY(`attempt_id`));
CREATE INDEX IF NOT EXISTS `index_rules_import_attempt_started` ON `rules_import_attempt` (`started_at_epoch_seconds`, `started_at_nano`, `attempt_id`);
CREATE VIRTUAL TABLE IF NOT EXISTS `rules_text_fts` USING FTS5(`title`, `text`, `corpus_id` UNINDEXED, `provider` UNINDEXED, `local_id` UNINDEXED, tokenize=`unicode61 remove_diacritics 2`);
CREATE TABLE IF NOT EXISTS `acquisition_job` (`job_id` TEXT NOT NULL, `payload_version` INTEGER NOT NULL, `plan_payload` TEXT NOT NULL, `plan_sha256` TEXT NOT NULL, `state` TEXT NOT NULL, `phase` TEXT NOT NULL, `revision` INTEGER NOT NULL, `attempt` INTEGER NOT NULL, `owner_token` TEXT, `created_seconds` INTEGER NOT NULL, `created_nano` INTEGER NOT NULL, `updated_seconds` INTEGER NOT NULL, `updated_nano` INTEGER NOT NULL, `started_seconds` INTEGER, `started_nano` INTEGER, `consent_id` TEXT, `partial_key` TEXT NOT NULL, `durable_offset` INTEGER NOT NULL, `transferred_bytes` INTEGER NOT NULL, `record_count` INTEGER NOT NULL, `page_count` INTEGER NOT NULL, `expected_records` INTEGER, `next_page_uri` TEXT, `first_page_sha256` TEXT, `final_uri` TEXT, `strong_etag` TEXT, `last_modified` TEXT, `expected_representation_bytes` INTEGER, `response_encoding` TEXT, `failure_payload` TEXT, PRIMARY KEY(`job_id`));
CREATE INDEX IF NOT EXISTS `index_acquisition_job_state_created` ON `acquisition_job` (`state`, `created_seconds`, `created_nano`, `job_id`);
CREATE INDEX IF NOT EXISTS `index_acquisition_job_created` ON `acquisition_job` (`created_seconds`, `created_nano`, `job_id`);
CREATE UNIQUE INDEX IF NOT EXISTS `index_acquisition_job_partial_key` ON `acquisition_job` (`partial_key`);
CREATE TABLE IF NOT EXISTS `acquisition_artifact` (`job_id` TEXT NOT NULL, `artifact_key` TEXT NOT NULL, `byte_count` INTEGER NOT NULL, `sha256` TEXT NOT NULL, `framing` TEXT NOT NULL, `compression` TEXT NOT NULL, `verified_payload` TEXT NOT NULL, `payload_version` INTEGER NOT NULL, `completed_seconds` INTEGER NOT NULL, `completed_nano` INTEGER NOT NULL, PRIMARY KEY(`job_id`), FOREIGN KEY(`job_id`) REFERENCES `acquisition_job`(`job_id`) ON UPDATE NO ACTION ON DELETE CASCADE );
