CREATE TABLE IF NOT EXISTS `acquisition_origin_cooldown` (`origin` TEXT NOT NULL, `revision` INTEGER NOT NULL, `interval_seconds` INTEGER, `interval_nano` INTEGER, PRIMARY KEY(`origin`));
